$data = stream_get_contents(STDIN);
$p = strpos($data, ">THREE");
if ($p === false) {
    $seq = '';
} else {
    $nl = strpos($data, "\n", $p);
    if ($nl === false) {
        $seq = '';
    } else {
        $start = $nl + 1;
        $end = strpos($data, "\n>", $start);
        if ($end === false) $end = strlen($data);
        $seq = substr($data, $start, $end - $start);
    }
}
unset($data);
