$n = strlen($seq);

function report($counts, $total) {
    $keys = array_keys($counts);
    usort($keys, function ($a, $b) use ($counts) {
        if ($counts[$a] != $counts[$b]) return $counts[$b] <=> $counts[$a];
        return strcmp($a, $b);
    });
    foreach ($keys as $k) {
        printf("%s %.3f\n", $k, $counts[$k] * 100.0 / $total);
    }
    echo "\n";
}

// 1-mers and 2-mers
$c1 = array_fill(0, 256, 0);
$c2 = array_fill(0, 65536, 0);
if ($n > 0) {
    $prev = ord($seq[0]);
    $c1[$prev]++;
    for ($i = 1; $i < $n; $i++) {
        $c = ord($seq[$i]);
        $c1[$c]++;
        $c2[($prev << 8) | $c]++;
        $prev = $c;
    }
}
$r1 = [];
foreach ($c1 as $c => $v) if ($v > 0) $r1[chr($c)] = $v;
$r2 = [];
foreach ($c2 as $c => $v) if ($v > 0) $r2[chr($c >> 8) . chr($c & 255)] = $v;
if ($n >= 1) report($r1, $n);
if ($n >= 2) report($r2, $n - 1);

foreach (["GGT", "GGTA", "GGTATT", "GGTATTTTAATT", "GGTATTTTAATTTATAGT"] as $f) {
    $cnt = 0;
    $pos = 0;
    while (($pos = strpos($seq, $f, $pos)) !== false) {
        $cnt++;
        $pos++;
    }
    echo $cnt, "\t", $f, "\n";
}
